CREATE TABLE city_china(
    id BIGINT(20) UNSIGNED NOT NULL PRIMARY KEY AUTO_INCREMENT COMMENT 'Primary Key',
    code VARCHAR(64) NOT NULL COMMENT '编码',
    parent_code VARCHAR(64) COMMENT '父级编码',
    name VARCHAR(64) NOT NULL COMMENT '城市',
    type INT NOT NULL DEFAULT 0 COMMENT '城市类型',
    first_letter VARCHAR(10) NOT NULL COMMENT '拼音首字母',
    pinyin VARCHAR(128) NOT NULL COMMENT '城市完整拼音',
    zip_code VARCHAR(64) NOT NULL DEFAULT '0' COMMENT '邮编',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) COMMENT '中国城市';

